  if (cache.has(key)) return cache.get(key);
  const res = await fetch("/api/search?q=" + encodeURIComponent(key), { signal });
  if (!res.ok) throw new Error("search failed: " + res.status);
  const data = await res.json();
  cache.set(key, data);
  return data;
}

